{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "parameters": {
    "namePrefix": {
      "defaultValue": "hrbdemo",
      "minLength": 3,
      "maxLength": 11,
      "type": "String"
    },
    "location": {
      "defaultValue": "eastus",
      "type": "String",
      "metadata": {
        "description": "Location for all resources. F0 Document Intelligence is available in eastus, westus2, westeurope."
      }
    },
    "foundryLocation": {
      "defaultValue": "eastus",
      "type": "String",
      "metadata": {
        "description": "Foundry / AOAI location. gpt-4o-mini available in eastus, eastus2, swedencentral, etc."
      }
    },
    "principalId": {
      "defaultValue": "",
      "type": "String",
      "metadata": {
        "description": "Object id (Entra) of the developer/principal that should get data-plane access for the demo."
      }
    },
    "principalType": {
      "defaultValue": "User",
      "allowedValues": [
        "User",
        "Group",
        "ServicePrincipal"
      ],
      "type": "String",
      "metadata": {
        "description": "Principal type for the principalId role assignment."
      }
    }
  },
  "variables": {
    "suffix": "[uniqueString(resourceGroup().id)]",
    "storageName": "[toLower(format('{0}st{1}', parameters('namePrefix'), variables('suffix')))]",
    "diName": "[format('{0}-di-{1}', parameters('namePrefix'), variables('suffix'))]",
    "aoaiName": "[format('{0}-aoai-{1}', parameters('namePrefix'), variables('suffix'))]",
    "aiName": "[format('{0}-ai-{1}', parameters('namePrefix'), variables('suffix'))]",
    "lawName": "[format('{0}-law-{1}', parameters('namePrefix'), variables('suffix'))]",
    "kvName": "[format('{0}kv{1}', parameters('namePrefix'), take(variables('suffix'), 8))]",
    "storageBlobDataContributor": "[format('/subscriptions/{0}/providers/Microsoft.Authorization/roleDefinitions/ba92f5b4-2d11-453d-a403-e96b0029c9fe', subscription().subscriptionId)]",
    "cognitiveServicesUser": "[format('/subscriptions/{0}/providers/Microsoft.Authorization/roleDefinitions/a97b65f3-24c7-4388-baec-2e87135dc908', subscription().subscriptionId)]"
  },
  "resources": [
    {
      "type": "Microsoft.Storage/storageAccounts",
      "apiVersion": "2023-05-01",
      "name": "[variables('storageName')]",
      "location": "[parameters('location')]",
      "sku": {
        "name": "Standard_LRS"
      },
      "kind": "StorageV2",
      "properties": {
        "minimumTlsVersion": "TLS1_2",
        "allowBlobPublicAccess": false,
        "allowSharedKeyAccess": true,
        "supportsHttpsTrafficOnly": true
      }
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}', variables('storageName'), 'default')]",
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts', variables('storageName'))]"
      ],
      "properties": {}
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices/containers",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}/{2}', variables('storageName'), 'default', 'incoming')]",
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices', variables('storageName'), 'default')]"
      ]
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices/containers",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}/{2}', variables('storageName'), 'default', 'output')]",
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices', variables('storageName'), 'default')]"
      ]
    },
    {
      "type": "Microsoft.Storage/storageAccounts/blobServices/containers",
      "apiVersion": "2023-05-01",
      "name": "[format('{0}/{1}/{2}', variables('storageName'), 'default', 'training')]",
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts/blobServices', variables('storageName'), 'default')]"
      ]
    },
    {
      "type": "Microsoft.CognitiveServices/accounts",
      "apiVersion": "2024-10-01",
      "name": "[variables('diName')]",
      "location": "[parameters('location')]",
      "sku": {
        "name": "F0"
      },
      "kind": "FormRecognizer",
      "identity": {
        "type": "SystemAssigned"
      },
      "properties": {
        "customSubDomainName": "[variables('diName')]",
        "publicNetworkAccess": "Enabled",
        "disableLocalAuth": false
      }
    },
    {
      "type": "Microsoft.CognitiveServices/accounts",
      "apiVersion": "2024-10-01",
      "name": "[variables('aoaiName')]",
      "location": "[parameters('foundryLocation')]",
      "sku": {
        "name": "S0"
      },
      "kind": "OpenAI",
      "identity": {
        "type": "SystemAssigned"
      },
      "properties": {
        "customSubDomainName": "[variables('aoaiName')]",
        "publicNetworkAccess": "Enabled"
      }
    },
    {
      "type": "Microsoft.CognitiveServices/accounts/deployments",
      "apiVersion": "2024-10-01",
      "name": "[format('{0}/{1}', variables('aoaiName'), 'gpt-4o-mini')]",
      "dependsOn": [
        "[resourceId('Microsoft.CognitiveServices/accounts', variables('aoaiName'))]"
      ],
      "sku": {
        "name": "GlobalStandard",
        "capacity": 10
      },
      "properties": {
        "model": {
          "format": "OpenAI",
          "name": "gpt-4o-mini",
          "version": "2024-07-18"
        }
      }
    },
    {
      "type": "Microsoft.OperationalInsights/workspaces",
      "apiVersion": "2023-09-01",
      "name": "[variables('lawName')]",
      "location": "[parameters('location')]",
      "properties": {
        "sku": {
          "name": "PerGB2018"
        },
        "retentionInDays": 30
      }
    },
    {
      "type": "Microsoft.Insights/components",
      "apiVersion": "2020-02-02",
      "name": "[variables('aiName')]",
      "location": "[parameters('location')]",
      "dependsOn": [
        "[resourceId('Microsoft.OperationalInsights/workspaces', variables('lawName'))]"
      ],
      "kind": "web",
      "properties": {
        "Application_Type": "web",
        "WorkspaceResourceId": "[resourceId('Microsoft.OperationalInsights/workspaces', variables('lawName'))]"
      }
    },
    {
      "type": "Microsoft.KeyVault/vaults",
      "apiVersion": "2024-04-01-preview",
      "name": "[variables('kvName')]",
      "location": "[parameters('location')]",
      "properties": {
        "sku": {
          "family": "A",
          "name": "standard"
        },
        "tenantId": "[subscription().tenantId]",
        "enableRbacAuthorization": true,
        "enableSoftDelete": true,
        "softDeleteRetentionInDays": 7,
        "publicNetworkAccess": "Enabled"
      }
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "name": "[guid(resourceId('Microsoft.Storage/storageAccounts', variables('storageName')), parameters('principalId'), 'blob-contrib-dev')]",
      "dependsOn": [
        "[resourceId('Microsoft.Storage/storageAccounts', variables('storageName'))]"
      ],
      "properties": {
        "roleDefinitionId": "[variables('storageBlobDataContributor')]",
        "principalId": "[parameters('principalId')]",
        "principalType": "[parameters('principalType')]"
      },
      "scope": "[format('Microsoft.Storage/storageAccounts/{0}', variables('storageName'))]",
      "condition": "[not(empty(parameters('principalId')))]"
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "name": "[guid(resourceId('Microsoft.CognitiveServices/accounts', variables('diName')), parameters('principalId'), 'cog-user-dev')]",
      "dependsOn": [
        "[resourceId('Microsoft.CognitiveServices/accounts', variables('diName'))]"
      ],
      "properties": {
        "roleDefinitionId": "[variables('cognitiveServicesUser')]",
        "principalId": "[parameters('principalId')]",
        "principalType": "[parameters('principalType')]"
      },
      "scope": "[format('Microsoft.CognitiveServices/accounts/{0}', variables('diName'))]",
      "condition": "[not(empty(parameters('principalId')))]"
    },
    {
      "type": "Microsoft.Authorization/roleAssignments",
      "apiVersion": "2022-04-01",
      "name": "[guid(resourceId('Microsoft.CognitiveServices/accounts', variables('aoaiName')), parameters('principalId'), 'cog-user-dev')]",
      "dependsOn": [
        "[resourceId('Microsoft.CognitiveServices/accounts', variables('aoaiName'))]"
      ],
      "properties": {
        "roleDefinitionId": "[variables('cognitiveServicesUser')]",
        "principalId": "[parameters('principalId')]",
        "principalType": "[parameters('principalType')]"
      },
      "scope": "[format('Microsoft.CognitiveServices/accounts/{0}', variables('aoaiName'))]",
      "condition": "[not(empty(parameters('principalId')))]"
    }
  ],
  "outputs": {
    "storageAccountName": {
      "type": "String",
      "value": "[variables('storageName')]"
    },
    "diEndpoint": {
      "type": "String",
      "value": "[reference(resourceId('Microsoft.CognitiveServices/accounts', variables('diName')), '2024-10-01').endpoint]"
    },
    "aoaiEndpoint": {
      "type": "String",
      "value": "[reference(resourceId('Microsoft.CognitiveServices/accounts', variables('aoaiName')), '2024-10-01').endpoint]"
    },
    "aoaiDeployment": {
      "type": "String",
      "value": "gpt-4o-mini"
    },
    "appInsightsName": {
      "type": "String",
      "value": "[variables('aiName')]"
    },
    "keyVaultName": {
      "type": "String",
      "value": "[variables('kvName')]"
    }
  }
}

